def page(p,title,desc,body,active='',article=None):
 canonical=HOST+u(p);schema={'@context':'https://schema.org','@type':'Article' if article else 'WebPage','name':title,'url':canonical,'inLanguage':'en'}
 if article:schema.update(headline=title,datePublished='2026-11-02',author={'@type':'Organization','name':'Zawatu Editorial'})
 text=f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="theme-color" content="#17251e"><title>{e(title)} — Zawatu</title><meta name="description" content="{e(desc)}"><link rel="canonical" href="{e(canonical)}"><meta property="og:title" content="{e(title)}"><meta property="og:description" content="{e(desc)}"><meta property="og:url" content="{e(canonical)}"><meta property="og:type" content="{"article" if article else "website"}"><link rel="icon" type="image/svg+xml" href="{u("assets/favicon.svg")}"><link rel="alternate" type="application/rss+xml" href="{u("feed.xml")}" title="Zawatu Blog"><link rel="stylesheet" href="{u("assets/site.css")}"><script type="application/ld+json">{json.dumps(schema).replace("<","&lt;")}</script><script defer src="{u("assets/site.js")}"></script></head><body>{header(active)}<main id="main">{body}</main>{footer()}</body></html>'
 dest=O/p/'index.html' if p else O/'index.html';dest.parent.mkdir(parents=True,exist_ok=True);dest.write_text(text);P.append(p)
def hero(label,title,desc):return f'<section class="page-hero wrap"><p class="eyebrow">{label}</p><h1>{title}</h1><p class="lede">{desc}</p></section>'
