 labels=['A CLEARER<br><em>MESSAGE.</em>','THE GIFT.<br><em>THE OFFER.</em>','BETTER<br><em>CONNECTIONS.</em>','THE STORY<br><em>BEHIND IT.</em>','THE RIGHT<br><em>PARTNER.</em>','BEYOND<br><em>THE VIEWS.</em>']
 return f'<article class="article-card" data-category="{e(x["category"])}" data-search="{e(x["title"]+" "+x["category"])}"><a href="{u("blog/"+x["slug"]+"/")}"><div class="article-art tone-{i%3}"><span>{labels[i%6]}</span><small>ZAWATU / PERSPECTIVES</small></div><p class="article-meta">{x["category"].upper()} · INSIGHT</p><h3>{e(x["title"])}</h3><span class="read">Read the story ↗</span></a></article>'
