 for slug,n,title,short,desc,items in SERV:page('services/'+slug+'/',title,desc,hero('EXPERTISE / '+n,title,short)+f'<section class="section wrap"><div class="intro-grid"><div class="number-panel">{n}<span>{title.upper()}</span></div><div><p class="lede">{desc}</p><h2>What we can<br><em>work on.</em></h2><ul class="deliverables">'+''.join(f'<li>{x}</li>' for x in items)+'</ul><p class="fine">The final scope, timing and indicators are agreed before work starts. Audience response, media coverage and commercial outcomes are not guaranteed.</p></div></div></section>'+cta(),'services')
 page('about/','About Zawatu','Independent spirit and international outlook. Discover the Zawatu approach.',hero('ABOUT ZAWATU','Independent spirit.<br><em>International outlook.</em>','Media, creative thinking and commercial relationships, brought together to help good ideas find their next opportunity.')+'<section class="section wrap"><div class="intro-grid"><h2>Understand the need.<br><em>Build the connection.</em></h2><div><p>A business can have a strong offer and still need a clearer story, a better way to present it or the right partner to move forward. That is where our work begins.</p><p>We are based in Burundi and welcome relevant projects across borders. Language, geography, working arrangements and delivery requirements are discussed for each engagement.</p></div></div></section><section class="section wrap soft"><div class="three-grid"><article><h3>Clarity</h3><p>Help your audience understand the offer and its next step.</p></article><article><h3>Creativity</h3><p>Connect a fresh idea with a real need or occasion.</p></article><article><h3>Trust</h3><p>Clear scope, identified sponsorship and grounded reporting.</p></article></div></section>'+cta(),'about')
 body=hero('THE IDEA LAB','Fresh thinking.<br><em>Practical connections.</em>','Illustrative concepts that show our approach. These are not completed client projects.')
 for n,t,d in [('01','A gift that travels.','A useful branded gift supports a clear customer offer. A retailer, supplier and customer each have a reason to participate.'),('02','Discover it in person.','Complementary brands share a discovery day with demonstrations and clearly identified places to buy.'),('03','Meet around a real need.','Buyer–supplier conversations are prepared from purchasing requirements collected before the event.')]:body+=f'<section class="section wrap"><div class="concept-row"><span class="concept-number">{n}</span><div><span class="eyebrow">CONCEPT STUDY</span><h2>{t}</h2><p class="lede">{d}</p><p>Success starts with confirmed participants, clear responsibilities, a funded budget and a realistic follow-up plan.</p>{a("contact/","Discuss a similar idea ↗","text-link")}</div></div></section>'
 page('campaigns/','Our approach','Campaign concepts that connect customers, businesses and suppliers.',body+cta(),'campaigns')
 cats=sorted({x['category'] for x in ART});filters='<button data-filter="all" aria-pressed="true">All stories</button>'+''.join(f'<button data-filter="{e(c)}" aria-pressed="false">{e(c)}</button>' for c in cats)
 page('blog/','The Blog','Practical perspectives on brands, campaigns and commercial connections.',hero('THE ZAWATU BLOG','A little perspective.<br><em>A world of possibility.</em>','Practical ideas on brands, campaigns and the connections that help businesses move forward.')+f'<section class="section wrap"><div class="journal-tools"><div class="filters" role="group" aria-label="Categories">{filters}</div><label class="search-label">Search the blog<input id="article-search" type="search" placeholder="Brand, gift, partner…"></label></div><p id="result-count" class="fine" role="status">{len(ART)} articles</p><div class="articles">'+''.join(card(x,i) for i,x in enumerate(ART))+'</div><p id="no-results" hidden>No stories match. Try another word or category.</p><div class="editorial-note"><span class="eyebrow">OUR EDITORIAL APPROACH</span><p>Useful perspectives and clearly identified commercial collaborations. These opening articles are general editorial guides.</p>'+a('feed.xml','Follow via RSS ↗','text-link')+'</div></section>','blog')
 for x in ART:page('blog/'+x['slug']+'/',x['title'],x['title'],f'<article class="article-page wrap"><nav class="breadcrumb" aria-label="Breadcrumb">{a("blog/","The Blog")} / {e(x["category"])}</nav><span class="eyebrow">{e(x["category"].upper())}</span><h1>{e(x["title"])}</h1><p class="byline">Zawatu Editorial · 2 November 2026 · Practical guide</p><div class="article-body">{x["body"]}</div><div class="article-end">{a("consultation/","Explore a consultation ↗","text-link")}<button class="share-link">Copy article link</button><span class="share-status" role="status"></span></div></article>','blog',x)
 page('partnerships/','Partnerships','Collaborate with Zawatu on media, campaigns and commercial opportunities.',hero('PARTNER WITH US','Different strengths.<br><em>A shared opportunity.</em>','We welcome relevant conversations with brands, sponsors, creators, media, suppliers and organisers, locally and internationally.')+'<section class="section wrap"><div class="three-grid"><article><h3>Brands & sponsors</h3><p>Support a defined series or campaign with clear placements, dates and reporting.</p></article><article><h3>Creators & media</h3><p>Bring a story, production skill or distribution opportunity. Rights and compensation are agreed in advance.</p></article><article><h3>Suppliers & venues</h3><p>Share your capabilities and delivery arrangements. An introduction is not an order.</p></article></div></section>'+cta())
 booking=S.get('booking_url','');valid=urlsplit(booking).scheme=='https' and urlsplit(booking).hostname in ['calendly.com','www.calendly.com']
