 request=f'<form id="appointment-form" data-email="{e(S["email"])}"><label>Your name<input name="name" required autocomplete="name" maxlength="120"></label><label>Your email<input name="email" type="email" required autocomplete="email" maxlength="200"></label><div class="field-grid"><label>Preferred date<input name="date" type="date" required></label><label>Preferred time<input name="time" type="time" required></label></div><label>Your time zone<input name="timezone" required maxlength="120" placeholder="Europe/Paris or Africa/Bujumbura"></label><label>Your objective<textarea name="details" required maxlength="4000" rows="4"></textarea></label><button class="solid" type="submit">Prepare consultation email ↗</button><p class="fine">Opens a draft in your email app. You review and send it. This website does not confirm appointments or collect payment.</p><p id="appointment-status" role="status"></p></form>'
 page('consultation/','Book a consultation','Request a focused conversation about your brand, campaign or partnership opportunity.',hero('PRIVATE CONSULTATIONS','Make room<br><em>for your next move.</em>','Bring your challenge, context and questions. We agree the scope, fee and meeting arrangements before confirmation.')+f'<section class="section wrap"><div class="booking-card"><div><span class="eyebrow">STRATEGY / BRAND / PARTNERSHIPS</span><h2>A fresh perspective<br><em>on your opportunity.</em></h2><ul class="deliverables"><li>Planned format: 45 minutes</li><li>Online or in person by arrangement</li><li>English or French</li><li>Fee agreed before confirmation</li></ul></div><aside><span class="booking-icon">↗</span><h3>Start with a conversation.</h3>{action}</aside></div></section><section class="section wrap soft" id="request"><div class="contact-grid"><div><span class="eyebrow">CONSULTATION REQUEST</span><h2>Your preferred date.<br><em>Subject to confirmation.</em></h2><p>This is a request, not a reservation. Availability, fee, payment instructions, cancellation and refund terms are confirmed before payment.</p></div>{request}</div></section>')
