 (O/'sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join('<url><loc>'+xe(HOST+u(p))+'</loc></url>' for p in P if p!='404/')+'</urlset>')
